//! skill_registry — GENERATED by crossing/orchestrator/gen-skill-registry.mjs, then EXTENDED BY
//! HAND. Maps a runtime dispatch name (skill-file basename, as JS importSkill(step.skill) resolves)
//! to its default-export twin fn, so action-run can reach every dispatchable skill. Each arm adapts
//! the twin's real signature to the uniform RunCtx. 781 arms; 134 skipped (see gen log).
//!
//! RE-RUNNING THE GENERATOR IS LOSSY — verified 2026-08-10, it drops 33 arms. The generator's model
//! is one default fn per file; the BE-conversion skills (be-surface-reads/writes, board-reads,
//! contract-reads, memory-reads, knowledge-reads) each export MANY named fns, and git-pending-list
//! has a bespoke signature. All 33 were added by hand and the generator cannot re-derive them, so it
//! emits a file that compiles and silently un-registers a third of the BE's routes. Regenerate only
//! against a backup, and diff before keeping the result.
#![allow(non_snake_case)]
use rusqlite::Connection;
use serde_json::{json, Value};

pub struct RunCtx<'a> {
    pub db: &'a Connection,
    pub actor: &'a str,
    pub source: &'a str,
}
impl<'a> RunCtx<'a> {
    /// A minimal JS-context-shaped Value for skills whose default takes (input, context).
    pub fn context_value(&self) -> Value {
        json!({ "actor": self.actor, "source": self.source })
    }
}

/// Dispatch a step-skill by name. Returns None if the name has no registered arm (caller decides
/// how to handle an unknown skill), Some(result) otherwise.
